/*
 * State layer: a currentColor overlay whose opacity shows hover (8%), focus (10%), and press (10%).
 * Set --state-layer-inset (e.g. -11px) to draw a 40px circle around a small control, and
 * --state-layer-color to override the color. The element needs a position (relative, absolute,
 * fixed); the layer paints between its background and its content.
 */
@utility state-layer {
  isolation: isolate;

  &::before {
    content: "";
    position: absolute;
    inset: var(--state-layer-inset, 0);
    z-index: -1;
    border-radius: var(--state-layer-radius, inherit);
    background-color: var(--state-layer-color, currentColor);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--md-sys-motion-fast-effects-duration)
      var(--md-sys-motion-fast-effects-easing);
  }

  @media (hover: hover) {
    &:hover::before {
      opacity: 0.08;
    }
  }

  &[data-highlighted]::before {
    opacity: 0.08;
  }

  &:focus-visible::before {
    opacity: 0.1;
  }

  &:active::before {
    opacity: 0.1;
  }

  &:disabled::before,
  &[data-disabled]::before,
  &[aria-disabled="true"]::before {
    opacity: 0;
  }
}

