  --animate-m3-circular-indeterminate: m3-circular-indeterminate 1.4s ease-in-out infinite;
  --animate-m3-wave: m3-wave 1s linear infinite;
  --animate-m3-morph:
    m3-morph 4.5s var(--md-sys-motion-default-spatial-easing) infinite, m3-spin 4.5s linear infinite;
}
